input.command:
python3 - <<'EOF'
p='bin/report.sh'
s=open(p).read()
s=s.replace('''  local file="${1:-}"

  if [[ -z''','''  local file="" json=0

  while (($#)); do
    case "$1" in
      --json) json=1 ;;
      *) file="$1" ;;
    esac
    shift
  done

  if [[ -z''')
s=s.replace("usage: %s FILE","usage: %s [--json] FILE")
s=s.replace('''  printf 'total=%d passed=%d failed=%d\\n' "${total}" "${passed}" "${failed}"''','''  if ((json)); then
    printf '{"total":%d,"passed":%d,"failed":%d}\\n' "${total}" "${passed}" "${failed}"
  else
    printf 'total=%d passed=%d failed=%d\\n' "${total}" "${passed}" "${failed}"
  fi''')
open(p,'w').write(s)
EOF
cat >> test/report.bats <<'EOF'

@test "--json prints the counters as JSON" {
  run "${REPO_ROOT}/bin/report.sh" --json "${REPO_ROOT}/data/sample.csv"
  [ "$status" -eq 0 ]
  [ "$output" = '{"total":3,"passed":2,"failed":1}' ]
}

@test "--json accepts the flag after the file" {
  run "${REPO_ROOT}/bin/report.sh" "${REPO_ROOT}/data/sample.csv" --json
  [ "$status" -eq 0 ]
  [ "$output" = '{"total":3,"passed":2,"failed":1}' ]
}

@test "--json without a file reports usage" {
  run "${REPO_ROOT}/bin/report.sh" --json
  [ "$status" -eq 64 ]
}

@test "--json reports a missing file" {
  run "${REPO_ROOT}/bin/report.sh" --json "${REPO_ROOT}/data/absent.csv"
  [ "$status" -eq 66 ]
}
EOF
sed -i 's/^`bin\/report.sh FILE` summarizes a CSV of build results as one line of counters./&\nPass `--json` to get the same counters as a JSON object./' README.md
make test

